export const classificationCases=[
  {id:'oscillator',formula:'oscillator',title:text('Sinüzoidal zorlama','Sinusoidal forcing'),pages:'6',role:text('Bilinmeyen y(x); ω sabit.','Unknown y(x); ω is constant.'),answers:{type:'ode',order:'2',linearity:'linear',coefficients:'constant',homogeneity:'nonhomogeneous'},hint:text('sin x bilinmeyenin değil, bağımsız değişkenin bir fonksiyonudur.','sin x is a function of the independent variable, not the unknown.'),reason:text('En yüksek türev y′′. y ve türevleri birinci kuvvette, katsayılar 1 ve ω² sabit. Zorlama sin x özdeş olarak sıfır değil.','The highest derivative is y′′. The unknown and derivatives occur linearly, with constant coefficients 1 and ω². The forcing sin x is not identically zero.')},
  {id:'squared',formula:'nonlinear',title:text('Türevin karesi','A squared derivative'),pages:'6',role:text('Bilinmeyen y(x).','Unknown y(x).'),answers:{type:'ode',order:'1',linearity:'nonlinear',coefficients:'na',homogeneity:'na'},hint:text('Türevin üssü ile türevin kaç kez alındığını ayır.','Separate the power of a derivative from how many times differentiation was performed.'),reason:text('(y′)², birinci türevin karesidir; mertebe 1 kalır. Bu kare doğrusallığı bozar. Katsayı ve homojenlik etiketleri burada doğrusal standart biçime göre sorulduğu için uygulanmaz.','(y′)² is the square of the first derivative, so order remains 1. The square makes the equation nonlinear. Coefficient and homogeneity labels here refer to linear standard form and are not applied.')},
  {id:'third',formula:'third',title:text('Eksik ara türev','A missing intermediate derivative'),pages:'7',role:text('Bilinmeyen y(x); standart mertebe için x>0 aralığını al.','Unknown y(x); use x>0 for standard order analysis.'),answers:{type:'ode',order:'3',linearity:'linear',coefficients:'variable',homogeneity:'nonhomogeneous'},hint:text('y′′ görünmese bile daha yüksek bir türev var mı?','Is there a higher derivative even though y′′ is absent?'),reason:text('En yüksek türev y′′′ olduğu için mertebe 3. x³ ve 5x bilinen değişken katsayılardır; bilinmeyeni doğrusal olmaktan çıkarmazlar. eˣ sıfır olmayan zorlamadır.','The highest derivative is y′′′, so the order is 3. The known variable coefficients x³ and 5x preserve linearity. eˣ is a nonzero forcing.')},
  {id:'swapped',formula:'swapped',title:text('Değişken rolleri ters','Reversed variable roles'),pages:'7',role:text('Bilinmeyen x=x(y), bağımsız değişken y; y>0.','Unknown x=x(y), independent variable y; y>0.'),answers:{type:'ode',order:'2',linearity:'linear',coefficients:'variable',homogeneity:'nonhomogeneous'},hint:text('√y bu örnekte bilinen bir katsayı mı, bilinmeyen fonksiyon mu?','Is √y a known coefficient or an unknown function in this example?'),reason:text('Türevler y’ye göre alınıyor. x ve d²x/dy² doğrusal; √y bağımsız değişkene bağlı katsayıdır. Sağdaki 5 nedeniyle denklem homojen değildir.','Differentiation is with respect to y. Both x and d²x/dy² occur linearly; √y is a coefficient depending on the independent variable. The forcing 5 makes it nonhomogeneous.')},
  {id:'bessel',formula:'bessel',title:text('Bessel denklemi','Bessel equation'),pages:'7',role:text('Bilinmeyen y(x); x>0, ν≥0 sabit.','Unknown y(x); x>0, ν≥0 is constant.'),answers:{type:'ode',order:'2',linearity:'linear',coefficients:'variable',homogeneity:'homogeneous'},hint:text('x², bilinmeyenin mi yoksa bağımsız değişkenin mi karesidir?','Is x² the square of the unknown or of the independent variable?'),reason:text('x² katsayısı doğrusallığı bozmaz. y′′ en yüksek türevdir, katsayılar x’e bağlıdır ve sağ taraf özdeş olarak 0’dır.','The coefficient x² does not destroy linearity. y′′ is the highest derivative, coefficients depend on x, and the forcing is identically zero.')},
  {id:'heat',formula:'heatType',title:text('Tek uzay boyutlu ısı','One spatial dimension of heat'),pages:'8',role:text('Bilinmeyen u(x,t); α>0 sabit.','Unknown u(x,t); α>0 is constant.'),answers:{type:'pde',order:'2',linearity:'linear',coefficients:'constant',homogeneity:'homogeneous'},hint:text('Bir uzay boyutu olsa da t bağımsız değişkenini saymayı unutma.','Count t as an independent variable even though there is only one spatial dimension.'),reason:text('u hem x’e hem t’ye bağlıdır. En yüksek türev uₓₓ, yani mertebe 2. Bütün türevler doğrusal ve katsayılar sabittir; standart biçimde dış zorlama 0’dır.','u depends on both x and t. The highest derivative uₓₓ makes the order 2. Derivatives occur linearly with constant coefficients and no external forcing.')},
  {id:'poisson',formula:'poisson',title:text('Poisson: f=1 özel hali','Poisson: the case f=1'),pages:'8',role:text('Bilinmeyen u(x,y). Kitaptaki f(x,y) yerine 1 seçildi.','Unknown u(x,y). The book’s f(x,y) is specialized to 1.'),answers:{type:'pde',order:'2',linearity:'linear',coefficients:'constant',homogeneity:'nonhomogeneous'},hint:text('İki ikinci türevi toplamak mertebeyi dört yapar mı?','Does adding two second derivatives make the order four?'),reason:text('Her terim ikinci mertebedendir; toplamın mertebesi de 2’dir. Sağdaki 1 nedeniyle sıfır fonksiyonu çözüm değildir.','Each derivative term has order 2, so their sum also has order 2. The forcing 1 means the zero function is not a solution.')},
  {id:'biharmonic',formula:'biharmonic',title:text('Karışık türevleri say','Count mixed derivatives'),pages:'8',role:text('Bilinmeyen u(x,y).','Unknown u(x,y).'),answers:{type:'pde',order:'4',linearity:'linear',coefficients:'constant',homogeneity:'homogeneous'},hint:text('uₓₓᵧᵧ için x’e göre iki ve y’ye göre iki türevi birlikte say.','For uₓₓᵧᵧ, count two x-derivatives and two y-derivatives together.'),reason:text('Karışık türev toplam dört kez türev alır. Bu, türevin karesi değildir. Bütün terimler doğrusal; katsayılar 1, 2, 1 ve zorlama sıfırdır.','The mixed derivative differentiates four times in total; it is not a squared derivative. All terms are linear, with coefficients 1, 2, 1 and zero forcing.')}
];

